final class LruCache<K, V> extends LinkedHashMap<K, V> {
    private final int capacity;
    LruCache(int capacity) { super(capacity, 0.75f, true); this.capacity = capacity; }
    @Override protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
        return size() > capacity;                 // evict least-recently-used
    }
}
// thread-safe handle:
Map<String, User> cache = Collections.synchronizedMap(new LruCache<>(10_000));
cache.remove(userId);                             // writer path: invalidate after commit

